"use client";
import { comments, sliderSettings } from "@/src/utils/data";
import Slider from "react-slick";
import { motion } from "framer-motion";
import { footerVariants, staggerChildren } from "@/src/utils/motion";

const People = () => {
  const updatedSliderSettings = {
    ...sliderSettings,
    autoplay: true,
    autoplaySpeed: 3200,
    pauseOnHover: true,
    infinite: true,
    adaptiveHeight: false,
    responsive: [
      {
        breakpoint: 1280,
        settings: { slidesToShow: 3, slidesToScroll: 1 },
      },
      {
        breakpoint: 1024,
        settings: { slidesToShow: 2, slidesToScroll: 1 },
      },
      {
        breakpoint: 640,
        settings: {
          slidesToShow: 1,
          slidesToScroll: 1,
          arrows: false,
          dots: true,
          centerMode: false,
        },
      },
    ],
  };

  return (
    <motion.section
      variants={staggerChildren}
      initial="hidden"
      whileInView="show"
      viewport={{ once: false, amount: 0.01 }}
      className="bg-gradient-to-b from-[#fffefe] via-[#fff8fc] to-[#fff3f8] px-4 pt-12 pb-16 md:px-8 lg:px-16"
    >
      <a className="block" id="people" />

      <motion.div variants={footerVariants} className="mx-auto max-w-6xl">
        <div className="mb-8 flex flex-col items-center gap-3 text-center">
          <span className="text-[1.65rem] font-bold text-[#671d8a] sm:text-[2rem] lg:text-[2.6rem]">
            People talk about us
          </span>

          <p className="max-w-2xl text-sm leading-relaxed text-[#5f5f5f] sm:text-base">
            Our clients rave about Lovely Looks Beauty Salon for exceptional
            services, from makeup and facials to manicures, pedicures, and
            haircuts.
          </p>

          <p className="max-w-2xl text-sm leading-relaxed text-[#5f5f5f] sm:text-base">
            We provide personalized care and outstanding results, leaving you
            feeling beautiful and confident.
          </p>
        </div>

        <div className="overflow-visible pt-8 pb-8">
          <Slider
            {...updatedSliderSettings}
            className="[&_.slick-list]:overflow-visible
              [&_.slick-list]:pb-5
              [&_.slick-list]:mx-[-6px]
              [&_.slick-track]:flex
              [&_.slick-slide]:h-auto
              [&_.slick-slide>div]:h-full
              [&_.slick-slide>div]:px-2
              [&_.slick-slide>div]:pt-12
              sm:[&_.slick-slide>div]:px-3
              [&_.slick-dots]:mt-5
              [&_.slick-dots_li_button:before]:text-[#a0146b]
              [&_.slick-dots_li_button:before]:text-[10px]
              [&_.slick-dots_li.slick-active_button:before]:text-[#7b1fa2]
              [&_.slick-slide.slick-active.slick-current+.slick-slide]:lg:scale-[1.03]
              [&_.slick-slide.slick-active.slick-current+.slick-slide]:lg:-translate-y-3
              [&_.slick-slide.slick-active.slick-current+.slick-slide]:lg:transition-all
              [&_.slick-slide.slick-active.slick-current+.slick-slide]:lg:duration-700
              [&_.slick-slide.slick-active.slick-current+.slick-slide]:lg:ease-out"
          >
            {comments.map((comment, i) => (
              <div key={i} className="h-full">
                <div
                  className="relative flex h-full min-h-[310px] flex-col overflow-visible rounded-[24px]
                    border border-white/70 bg-[linear-gradient(180deg,#ffffff_0%,#fff8fc_100%)]
                    px-4 pt-12 pb-6 shadow-[0_16px_36px_rgba(123,31,162,0.10)]
                    transition-all duration-300 hover:-translate-y-1
                    hover:shadow-[0_20px_42px_rgba(123,31,162,0.16)]
                    sm:min-h-[330px] sm:px-5 sm:pb-7 lg:min-h-[315px]"
                >
                  <div className="absolute left-1/2 top-4 -translate-x-1/2 text-[2.2rem] leading-none text-[#f3d3e7] sm:text-[2.5rem]">
                    ”
                  </div>

                  <img
                    src={comment.img}
                    alt={comment.name}
                    className="absolute -top-7 left-1/2 z-10 h-14 w-14 -translate-x-1/2 rounded-full
                      object-cover ring-4 ring-white shadow-[0_8px_18px_rgba(0,0,0,0.16)]
                      sm:h-16 sm:w-16"
                  />

                  <p
                    className="text-center text-[0.84rem] leading-6 text-[#2e2e2e]
                      sm:text-[0.9rem] sm:leading-7 lg:text-[0.92rem]"
                  >
                    {comment.comment}
                  </p>

                  <div className="my-4 w-full border-t border-[#f0dce9]" />

                  <div className="mt-auto flex flex-col items-center gap-1">
                    <span className="text-[0.95rem] font-semibold text-[#4d214f] sm:text-base">
                      {comment.name}
                    </span>

                    <span className="text-[0.68rem] uppercase tracking-[0.12em] text-[#b085a5] sm:text-[0.72rem]">
                      {comment.post}
                    </span>

                    <div className="mt-1.5 flex justify-center gap-0.5">
                      {Array.from({ length: 5 }).map((_, index) => (
                        <span
                          key={index}
                          className="text-[1rem] text-[#f4b400] sm:text-[1.05rem] lg:text-[1.1rem]"
                        >
                          ★
                        </span>
                      ))}
                    </div>
                  </div>
                </div>
              </div>
            ))}
          </Slider>
        </div>
      </motion.div>
    </motion.section>
  );
};

export default People;