"use client";

import { useBookingContext } from "@/src/components/Booking/BookingContext";

export default function TrailService() {
  const { openForm } = useBookingContext();

  return (
    <section className="bg-gradient-to-b from-white to-[#fff8fc] px-4 py-10 md:px-6 md:py-12">
      <div
        className="mx-auto flex max-w-[1180px] flex-col-reverse items-center gap-6 overflow-hidden rounded-[28px]
        border border-white/60 bg-gradient-to-r from-[#fde7d5] via-[#f7c7b7] to-[#efaa73]
        px-5 py-6 shadow-[0_16px_40px_rgba(91,15,47,0.12)] md:flex-row md:gap-8 md:px-8 md:py-8 lg:px-10"
      >
        <div className="w-full text-center md:w-[54%] md:text-left">
          <span
            className="mb-3 inline-flex rounded-full bg-white/70 px-4 py-1.5
            text-xs font-semibold uppercase tracking-[0.18em] text-[#8b1c8f]"
          >
            Exclusive Offer
          </span>

          <h2 className="mb-3 text-2xl font-extrabold leading-tight text-[rgb(168,8,126)] md:text-3xl lg:text-[2.9rem]">
            Free Trial Makeup Sessions
          </h2>

          <p className="mb-5 text-sm leading-7 text-[#000000] md:mx-0 md:text-lg">
            We offer professional free trial makeup sessions to help you
            discover the perfect look for your special day. Work with our
            experienced artists and enjoy a personalised beauty experience that
            enhances your natural glow with elegance and confidence.
          </p>

          <div className="flex flex-col items-center gap-3 sm:flex-row sm:justify-center md:justify-start">
            <button
              type="button"
              onClick={openForm}
              className="rounded-xl bg-[linear-gradient(90deg,#7b1fa2,#d81b60)] px-6 py-3 text-sm font-semibold text-white shadow-[0_10px_20px_rgba(216,27,96,0.2)] transition duration-200 hover:-translate-y-[1px] hover:opacity-95"
            >
              Book Now
            </button>

            <span className="text-sm font-medium text-[#6b213c]">
              *Limited-time complimentary bridal trial
            </span>
          </div>
        </div>

        <div className="flex w-full justify-center md:w-[46%] md:justify-end">
          <div
            className="relative overflow-hidden rounded-[24px] border border-white/70 bg-white/40 p-2
            shadow-[0_14px_30px_rgba(0,0,0,0.1)]"
          >
            <img
              src="https://res.cloudinary.com/dtiaycw2o/image/upload/v1756199688/home-trail_tqf8fz.webp"
              alt="Trial Makeup"
              className="h-auto w-[240px] rounded-[18px] object-cover md:w-[290px] lg:w-[330px]"
            />
          </div>
        </div>
      </div>
    </section>
  );
}