"use client";

import React, { useState, useEffect } from "react";
import { projectExperience, WhatDoIHelp } from "@/src/utils/data";
import { motion } from "framer-motion";
import { fadeIn, staggerContainer, textVariant } from "@/src/utils/motion";

const Experties = () => {
  const [makeupCompleted, setMakeupCompleted] = useState(0);
  const [happyClients, setHappyClients] = useState(0);

  const targetMakeups = 1100;
  const targetClients = 1500;

  useEffect(() => {
    const makeupInterval = setInterval(() => {
      setMakeupCompleted((prev) => {
        if (prev < targetMakeups) return prev + 1;
        clearInterval(makeupInterval);
        return prev;
      });
    }, 5);

    const clientInterval = setInterval(() => {
      setHappyClients((prev) => {
        if (prev < targetClients) return prev + 1;
        clearInterval(clientInterval);
        return prev;
      });
    }, 4);

    return () => {
      clearInterval(makeupInterval);
      clearInterval(clientInterval);
    };
  }, []);

  return (
    <section
      className="w-full bg-white bg-cover bg-center bg-no-repeat"
      style={{
        backgroundImage:
          "url('https://res.cloudinary.com/dtiaycw2o/image/upload/v1756199687/home-bg-1_mspklj.webp')",
      }}
    >
      <a className="block" id="experties" />

      <motion.div
        variants={staggerContainer}
        initial="hidden"
        whileInView="show"
        viewport={{ once: false, amount: 0.25 }}
        className="mx-auto flex max-w-6xl flex-wrap items-start justify-center gap-8 px-4 py-16"
      >
        {/* Left Side */}
        <div className="flex min-w-[300px] flex-1 flex-col gap-8">
          {projectExperience.map((exp, i) => (
            <motion.div
              key={i}
              variants={fadeIn("right", "tween", (i + 1) * 0.05, 0.3)}
              className="flex items-center gap-8 rounded-[20px] border border-[coral]
                p-6 transition-all duration-200 ease-out hover:cursor-pointer hover:shadow-lg"
            >
              <div
                className="flex h-20 w-20 shrink-0 items-center justify-center rounded-full p-2.5"
                style={{ background: exp.bg }}
              >
                <img
                  src={exp.icon}
                  alt={exp.name}
                  className="h-[45px] w-[45px]"
                />
              </div>

              <div className="flex flex-col gap-3">
                <span className="text-xl font-bold text-black">
                  {exp.name}
                </span>
                <span className="text-lg text-gray-800">
                  {exp.projects} Reviews
                </span>
              </div>
            </motion.div>
          ))}
        </div>

        {/* Right Side */}
        <motion.div
          variants={textVariant(0.5)}
          className="flex min-w-[300px] flex-1 flex-col gap-8 text-center sm:text-left"
        >
          <span className="inline-block text-3xl font-bold text-[#671d8a] transition-transform duration-500 ease-out md:text-3xl">
            What makes our beauty services unique?
          </span>

          {WhatDoIHelp.map((paragraph, i) => (
            <span
              key={i}
              className="text-sm leading-relaxed tracking-[0.04rem] text-gray-800 md:text-base"
            >
              {paragraph}
            </span>
          ))}

          {/* Stats */}
          <div className="flex flex-wrap items-center justify-center gap-10 text-center sm:justify-start sm:text-left md:gap-16">
            <div className="flex flex-col items-center gap-1 sm:items-start">
              <span className="text-4xl font-bold text-[#671d8a] md:text-3xl">
                {makeupCompleted}+
              </span>
              <span className="text-sm text-gray-800">Makeup Completed</span>
            </div>

            <div className="flex flex-col items-center gap-1 sm:items-start">
              <span className="text-4xl font-bold text-[#671d8a] md:text-3xl">
                {happyClients}+
              </span>
              <span className="text-sm text-gray-800">Happy Clients</span>
            </div>
          </div>
        </motion.div>
      </motion.div>
    </section>
  );
};

export default Experties;